select pid.id,pid.code,pid.name,pid.scenario,pit.interface_type_code,pit.interface_type_name,pw.pay_name,pid.create_time,pid.update_time,pid.enable
from pay_interface_define pid
left join pay_interface_type pit on pid.pay_interface_type_id = pit.id
left join pay_way pw on pid.pay_way_id = pw.id


